package com.example

import com.example.ExamQuestionHelper.QSpec

object MusicLiveExamRagaG10Bank2 {
    private const val T = "10 ශ්‍රේණියේ රාග — භූපාලි, බිලාවල්, කාෆි, ඛමාජ්"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("භූපාලි රාගයේ ත්‍රිතාල බණ්ඩිසයක් වන 'සෙලී සුගන්ධ දින රාත්' ගීතයෙහි ලය සාමාන්‍යයෙන් කෙබඳුද?", "මධ්‍ය ලය", "අති විලම්බිත ලය", "අනියත ජන කවි ලය", "චෞගුන් ලය පමණක්", "පාසල් O/L විෂය නිර්දේශයේ භූපාලි බණ්ඩිස් මධ්‍ය ලය ත්‍රිතාලයෙන් ඉගැන්වේ."),
        q("කිසියම් සිසුවෙකු 'ස රි ග ප ධ' වෙනුවට 'ස රි ග ම ප ධ' ගැයුවහොත් භූපාලි රාගයේ බිඳී යන රීතිය කුමක්ද?", "මධ්‍යමය වර්ජිත කිරීමේ රීතිය", "කෝමල ගාන්ධාර රීතිය", "තීව්‍ර මධ්‍යම රීතිය", "ෂඩ්ජ න්‍යාස රීතිය", "භූපාලිහි මධ්‍යමය සම්පූර්ණයෙන්ම අත්හැරිය යුතු ස්වරයකි."),
        q("ඛමාජ් රාගයේදී 'ස ග ම ප ධ නි සඃ' ගැයීමෙන් පසු ආපසු එන විට 'සඃ නි̱ ධ ප ම ග රි ස' ලෙස නිෂාදය කෝමල වීම හඳුන්වන්නේ කෙසේද?", "උභය නිෂාද භාවිතය", "ඒක නිෂාද භාවිතය", "නිෂාද වර්ජනය", "පංචම වර්ජනය", "ශුද්ධ නි සහ කෝමල නි දෙකම යෙදීම ඛමාජ් රාගයේ ප්‍රධාන ලක්ෂණයකි."),
        q("කාෆි රාගය සඳහා වයලීනය හෝ හාමෝනියම් වැයීමේදී ශුද්ධ ග සහ නි වෙනුවට තෝරාගත යුත්තේ මොනවාද?", "කෝමල ග (ග̱) සහ කෝමල නි (නි̱)", "කෝමල රි (රි̱) සහ කෝමල ධ (ධ̱)", "තීව්‍ර ම (ම්) සහ ශුද්ධ ග", "ශුද්ධ ධ සහ කෝමල රි", "කාෆි ථාටයේ අනිවාර්ය විකෘති ස්වර දෙක වන්නේ ග̱ සහ නි̱ ය."),
        q("බිලාවල් රාගයෙහි 'ලක්ෂණ ගීතයක්' ගැයීමේදී ගීතයේ වචන තුළින්ම ප්‍රකාශ වන්නේ කුමක්ද?", "බිලාවල් රාගයේ ථාටය, ජාතිය, වාදී-සංවාදී සහ ගායන සමය", "ගොයම් කැපීමේ ගැමි චාරිත්‍ර පිළිබඳ විස්තර", "බටහිර සිම්ෆනි වාද්‍ය භාණ්ඩ ලැයිස්තුව", "පහතරට යක්බෙර වාදන පද මාලාව", "ලක්ෂණ ගීතයක අන්තර්ගතය වන්නේ අදාළ රාගයේ ශාස්ත්‍රීය නීති රීති සමූහයයි."),
        q("භූපාලි රාගයේ 'ස' සහ 'ප' හැරුණු විට රාගයේ රසය වඩාත් මතු කරන ප්‍රධාන ස්වර යුගලය කුමක්ද?", "ගාන්ධාරය සහ ධෛවතය", "මධ්‍යමය සහ නිෂාදය", "කෝමල රිෂභය සහ තීව්‍ර මධ්‍යමය", "කෝමල ගාන්ධාරය සහ කෝමල නිෂාදය", "වාදී 'ග' සහ සංවාදී 'ධ' භූපාලි රාගයේ ජීව ස්වර දෙකයි."),
        q("ඛමාජ් රාගයේ 'ග' ස්වරය වාදී ස්වරය වීම නිසා බණ්ඩිස් ගායනයේදී වැඩිපුරම විශ්‍රාම ලබන්නේ කුමන ස්වරය මතද?", "ගාන්ධාරය (ග)", "රිෂභය (රි)", "ධෛවතය (ධ)", "මධ්‍යමය (ම)", "වාදී ස්වරය වන ග මත නිතර නැවතී විශ්‍රාම ගැනීම ඛමාජ් රාගයේ ස්වභාවයයි."),
        q("බිලාවල් රාගයේ 'ග ප ධ නි සඃ' යන ගමනේදී මඟහැරෙන මධ්‍යමය (ම) ආපසු අවරෝහණයේදී ගැයෙන්නේ කෙසේද?", "වක්‍ර ලෙස ම ග ම රි ස යනුවෙනි", "කෝමල මධ්‍යමයක් ලෙසිනි", "තීව්‍ර මධ්‍යමයක් ලෙසිනි", "සම්පූර්ණයෙන්ම වර්ජිත ලෙසිනි", "බිලාවල් රාගයේ අවරෝහණයේ 'ම ග ම රි ස' ලෙස මධ්‍යමය මිහිරිව යෙදේ."),
        q("10 ශ්‍රේණියේ රාග අතරින් ආරෝහණයේදී ස්වර 7 ම කිසිදු අඩුවක් නැතිව සම්පූර්ණයෙන් ගයන රාගය කුමක්ද?", "කාෆි රාගය", "භූපාලි රාගය", "ඛමාජ් රාගය", "දුර්ගා රාගය", "කාෆි (හා ශුද්ධ බිලාවල්) ආරෝහණයේ ස්වර 7ම ගනී. භූපාලි-දුර්ගා 5ක්ද ඛමාජ් 6ක්ද ගනී."),
        q("කාෆි රාගයේ 'ග̱' ස්වරය ස්පර්ශ කර නැවත 'රි' ස්වරයට පැමිණීමේදී ශිල්පියා පවත්වා ගත යුතු විනය කුමක්ද?", "ග ස්වරය කෝමල ස්ථානයෙන් ඉහළට නොගොස් ගැයීම", "ග ස්වරය සම්පූර්ණයෙන් අත්හැර ප ගැයීම", "රි ස්වරය කෝමල රි බවට හැරවීම", "මධ්‍යමය තීව්‍ර කිරීම", "කාෆිහි කෝමල ග ශුද්ධ ග බවට පත් නොවී රැකගැනීම අත්‍යවශ්‍ය වේ."),
        q("ඛමාජ් රාගයේ අන්තරාව ගායනයේදී 'ග ම ධ නි සඃ' හෝ 'ම ප ධ නි සඃ' ගයන විට භාවිත වන නිෂාදය කවරේද?", "ශුද්ධ නිෂාදය (නි)", "කෝමල නිෂාදය (නි̱)", "වර්ජිත නිෂාදය", "අතිතාර නිෂාදය", "ඉහළ තාර සඃ කරා යාමේදී සැමවිටම ශුද්ධ නිෂාදය භාවිත වේ."),
        q("දුර්ගා රාගයේ 'ධ ප ම ප ධ ම රි ස' යන ඛණ්ඩය තුළ දැකිය හැකි විශේෂ ලක්ෂණය කුමක්ද?", "ග සහ නි ස්වර දෙකම සම්පූර්ණයෙන් වර්ජිත වීම", "මධ්‍යමය තීව්‍ර වීම", "කෝමල රිෂභය යෙදීම", "සියලු ස්වර කෝමල වීම", "දුර්ගා රාගයේ ගාන්ධාරය සහ නිෂාදය නොයෙදේ."),
        q("දේශ් රාගය භූපාලි හෝ බිලාවල් රාගවලින් වෙනස් වන ප්‍රධාන ශ්‍රව්‍ය ලක්ෂණය කුමක්ද?", "නිෂාද ස්වර දෙකම යෙදී රි-ප වාදී සංවාදී වීම", "සියලුම ස්වර කෝමල වීම", "මධ්‍යමය තීව්‍ර වීම", "පංචමය වර්ජිත වීම", "ආරෝහණයේ ශුද්ධ නි සහ අවරෝහණයේ කෝමල නි සමඟ රි-ම-ප ගමන දේශ් රාගය වෙන් කරයි."),
        q("ශ්‍රී ලංකාවේ ජාතික හා දේශාභිමානී ගීත නිර්මාණයේදී 'වන්දේ මාතරම්' වැනි ප්‍රසිද්ධ ගීත නිමැවී ඇත්තේ කුමන රාගය ඇසුරෙන්ද?", "දේශ් රාගය", "තෝඩි රාගය", "භෛරව් රාගය", "මාරවා රාගය", "දේශාභිමානී හා ශෘංගාර රසය මවන දේශ් රාගය බොහෝ ජාතික ගී තනුවලට පදනම් විය."),
        q("භූපාලි රාගයේ 'ස රි ග ප ධ සඃ' ආරෝහණයේදී සංඛ්‍යාත්මකව ග සහ ධ අතර ඇති ස්වරය කුමක්ද?", "පංචමය (ප)", "මධ්‍යමය (ම)", "නිෂාදය (නි)", "රිෂභය (රි)", "ම වර්ජිත බැවින් ග ට පසු කෙළින්ම ප ද ඉන්පසු ධ ද හමු වේ."),
        q("ඛමාජ් රාගයේ 'ස ග ම ප' ආරෝහණ ගමන ආරම්භයේදී කෙළින්ම ස සිට ග වෙත යන්නේ ඇයි?", "රිෂභය ආරෝහණයේ වර්ජිත බැවින්", "රිෂභය කෝමල නිසා", "මධ්‍යමය තීව්‍ර නිසා", "ගාන්ධාරය වර්ජිත නිසා", "ඛමාජ් රාගයේ ආරෝහණයේදී රි අත්හැර ස සිට ග ට පැනීම නියමයකි."),
        q("කාෆි රාගයේ වාදී ස්වරය වන පංචමයෙන් අන්තරා කොටස ආරම්භ කිරීම සුදුසුද?", "ඔව්, ප-ධ-නි̱-සඃ ලෙස උත්තරාංගයේ සිට අන්තරාව ඇරඹේ", "නැත, කිසිදා ප ස්වරයෙන් අන්තරාව නොඇරඹේ", "අන්තරාව කෝමල රි ස්වරයෙන් පමණක් ඇරඹේ", "අන්තරාව මන්ද්‍ර ධ ස්වරයෙන් පමණක් ඇරඹේ", "බොහෝ බණ්ඩිස් ගීතවල අන්තරාව ප හෝ ම සිට තාර සඃ දක්වා ගමන් කරයි."),
        q("බිලාවල් රාගයට අයත් 'සප්ත ස්වර ගුන ගායේ' වැනි රචනයක් හඳුන්වන්නේ කුමන නමින්ද?", "ලක්ෂණ ගීතය", "ධමාර් ගීතය", "තාරානා ගීතය", "පැල් කවිය", "රාගයේ නියමයන් කියවෙන බැවින් මෙය ලක්ෂණ ගීතයකි."),
        q("රාගයක් වශයෙන් 'භූපාලි' සහ 'දේශ්කාර්' රාග දෙකේම සමාන ස්වර 5ක් (ස රි ග ප ධ) යෙදුණත් ඒවා වෙනස් වන්නේ කුමකින්ද?", "වාදී-සංවාදී ස්වර සහ ගායන සමය අනුවය", "දේශ්කාර්හි කෝමල රි යෙදෙන නිසාය", "භූපාලිහි තීව්‍ර ම යෙදෙන නිසාය", "දේශ්කාර්හි පංචමය වර්ජිත නිසාය", "භූපාලි ග-ධ වාදී-සංවාදී සහ රාත්‍රී රාගයකි; දේශ්කාර් ධ-ග සහ උදෑසන රාගයකි."),
        q("ඛමාජ් රාගයේ අවරෝහණයේදී 'ප ම ග රි ස' ලෙස එන විට අත් නොහැර අනිවාර්යයෙන්ම ගැයෙන ස්වරය කුමක්ද?", "රිෂභය (රි)", "තීව්‍ර මධ්‍යමය (ම්)", "කෝමල ගාන්ධාරය (ග̱)", "කෝමල ධෛවතය (ධ̱)", "ආරෝහණයේ වර්ජිත වූවත් අවරෝහණයේ රි ගැයේ."),
        q("කාෆි රාගයේ සමපාත ආරෝහණ අවරෝහණ සැකිල්ලට අනුව ස්වර කීයක් මුළුමනින්ම භාවිත වේද?", "ස්වර 7 ක්", "ස්වර 5 ක්", "ස්වර 6 ක්", "ස්වර 4 ක්", "සම්පූර්ණ-සම්පූර්ණ ජාතිය නිසා ස්වර 7ම භාවිත වේ."),
        q("10 ශ්‍රේණියේ O/L විෂය නිර්දේශයේදී රාග 4 ටම පොදුවේ බහුලව භාවිත කරන ප්‍රධාන තාලය කුමක්ද?", "ත්‍රිතාලය (මාත්‍රා 16)", "ඒක්තාලය (මාත්‍රා 12)", "ධමාර් තාලය (මාත්‍රා 14)", "සූලතාලය (මාත්‍රා 10)", "10 ශ්‍රේණියේ බණ්ඩිස් හා සර්ගම් බහුතරයක් ත්‍රිතාලයෙන් ඉගැන්වේ."),
        q("භූපාලි රාගයේ ආරෝහණයේ 'ස රි ග ප ධ සඃ' ගැයූ පසු සඃ සිට අවරෝහණයේ පළමුව හමුවන ස්වරය කුමක්ද?", "ධෛවතය (ධ)", "නිෂාදය (නි)", "පංචමය (ප)", "මධ්‍යමය (ම)", "නි වර්ජිත නිසා තාර සඃ සිට කෙළින්ම ධ වෙත බසියි."),
        q("ඛමාජ් රාගයේ ආරෝහණයේ ස සිට ග ට යාමෙන් පසු ග සිට ඉහළට යන මීළඟ ස්වරය කුමක්ද?", "මධ්‍යමය (ම)", "රිෂභය (රි)", "පංචමය (ප)", "නිෂාදය (නි)", "ස-ග-ම-ප-ධ-නි-සඃ පිළිවෙළ අනුව ග පසු ම හමු වේ."),
        q("බිලාවල් රාගය 10 ශ්‍රේණියේ සිසුන් සඳහා කවර ගායන සමයකට අයත් ප්‍රධාන රාගයක් ලෙස උගන්වයිද?", "දිවා පළමු ප්‍රහරය (උදෑසන)", "රාත්‍රී පළමු ප්‍රහරය", "මධ්‍යම රාත්‍රිය", "සන්ධ්‍යා සමය", "බිලාවල් උදෑසන පළමු ප්‍රහරයේ ප්‍රබෝධමත් රාගයයි."),
        q("කාෆි රාගය හඳුනාගැනීමේදී ගායකයා කෝමල නිෂාදයේ සිට ධෛවතයට සහ පංචමයට බැසීමේදී කුමන ස්වරය කෝමල විය යුතුද?", "නිෂාදය (නි̱)", "ධෛවතය (ධ)", "පංචමය (ප)", "මධ්‍යමය (ම)", "කාෆි රාගයේ ධ ශුද්ධ වන අතර නි කෝමල වේ."),
        q("භූපාලි රාගයේ මන්ද්‍ර සප්තකයේදී වැඩිපුරම යොදාගන්නා ස්වර දෙක මොනවාද?", "මන්ද්‍ර ධ සහ මන්ද්‍ර ප", "මන්ද්‍ර නි සහ මන්ද්‍ර ම", "මන්ද්‍ර කෝමල රි සහ ධ", "මන්ද්‍ර තීව්‍ර ම සහ නි", "ම සහ නි වර්ජිත බැවින් මන්ද්‍ර සප්තකයේ ප̣ හා ධ̣ යොදයි."),
        q("ඛමාජ් රාගය සඳහා පහත දැක්වෙන ස්වර පෙළ අතුරින් නිවැරදි ආරෝහණය කුමක්ද?", "ස ග ම ප ධ නි සඃ", "ස රි ග ම ප ධ නි සඃ", "ස ග ම ප ධ නි̱ සඃ", "ස රි ග ප ධ සඃ", "ආරෝහණයේ රි වර්ජිත වන අතර නි ශුද්ධ වේ."),
        q("කාෆි රාගය සඳහා නිවැරදි අවරෝහණ ස්වර මාලාව තෝරන්න.", "සඃ නි̱ ධ ප ම ග̱ රි ස", "සඃ නි ධ ප ම ග රි ස", "සඃ නි̱ ධ̱ ප ම ග̱ රි̱ ස", "සඃ ධ ප ග රි ස", "කාෆි අවරෝහණයේ ග සහ නි කෝමල වී අනෙක් ස්වර ශුද්ධ වේ."),
        q("බිලාවල් රාගය ගායනයේදී 'ග, රි, ස' සහ 'ධ, ප' ස්වර සමඟ මිහිරිව යෙදෙන වක්‍ර චලනය කුමක්ද?", "ම ග ම රි ස", "ග̱ රි̱ ස", "ම් ප ධ නි", "නි̱ ධ ප ග̱", "ම ග ම රි ස යනු බිලාවල් රාගයේ ප්‍රධාන වක්‍ර සමාප්තියයි."),
        q("දුර්ගා රාගයේ අවරෝහණය නිවැරදිව දැක්වෙන ස්වර මාලාව කුමක්ද?", "සඃ ධ ප ම රි ස", "සඃ නි ධ ප ම ග රි ස", "සඃ ධ ප ග රි ස", "සඃ නි̱ ධ ප ම ග̱ රි ස", "දුර්ගා රාගයේ ග සහ නි වර්ජිත බැවින් අවරෝහණය සඃ ධ ප ම රි ස වේ."),
        q("දේශ් රාගයේදී 'ප ධ ම ග රි ග නි̣ ස' යන ඛණ්ඩය අවසානයේ යෙදෙන නි̣ ස්වරය කුමන සප්තකයට අයත්ද?", "මන්ද්‍ර සප්තකයට", "තාර සප්තකයට", "මධ්‍ය සප්තකයට", "වර්ජිත සප්තකයට", "රාග ගායනයේදී ස ට පහළින් යෙදෙන නි̣ මන්ද්‍ර නිෂාදයයි."),
        q("භූපාලි රාගයේ මධ්‍ය 'ග' වාදී ස්වරය සමඟ 'සංවාදී' භාවයෙන් බැඳෙන ස්වරය කුමක්ද?", "ධෛවතය (ධ)", "රිෂභය (රි)", "පංචමය (ප)", "මධ්‍යමය (ම)", "ග සිට සප්තකයේ සිව්වන/පස්වන පරතරයෙන් ධ සංවාදී ස්වරය වේ."),
        q("බිලාවල් රාගයෙන් ශුද්ධ ධෛවතය වාදී ස්වරය ලෙස යෙදෙන විට සංවාදී ස්වරය වන ගාන්ධාරය පිහිටන්නේ කොතැනද?", "පූර්වාංගයේ", "උත්තරාංගයේ", "මන්ද්‍ර කලාපයේ පමණක්", "තාර කලාපයේ පමණක්", "වාදී ධ උත්තරාංගයේද සංවාදී ග පූර්වාංගයේද පිහිටයි."),
        q("ඛමාජ් රාගයේ ආරෝහණයේ ශුද්ධ නි සහ අවරෝහණයේ කෝමල නි̱ මාරු වීමේදී ගායකයා කෙබඳු අවධානයක් යොමු කළ යුතුද?", "නිවැරදිව ශුද්ධ හා කෝමල ශ්‍රැති වෙන් කර ගැයීම", "නිෂාදය සම්පූර්ණයෙන් අත්හැරීම", "ධෛවතය කෝමල කිරීම", "මධ්‍යමය තීව්‍ර කිරීම", "ඛමාජ් රාගයේ අලංකාරය රැඳී ඇත්තේ නි ස්වර දෙක නිවැරදිව පෙන්වීම මතය."),
        q("කාෆි රාගය භාවිත කොට ශ්‍රී ලංකාවේ නිර්මාණය වූ සුගම හා නූර්ති ගීතවල ඇති සුවිශේෂී රසය කුමක්ද?", "ශෘංගාර හා කාව්‍යමය මිහිරියාව", "රෞද්‍ර හා යුදමය භීතිය", "බීභත්ස හා අප්‍රසන්න බව", "නිහඬ ශෝකාන්තය පමණක්", "කාෆි රාගය මිහිරි නාද රටා නිසා නාට්‍ය හා සරල ගීවල බහුලව යොදාගෙන ඇත."),
        q("10 ශ්‍රේණියේ රාග පුහුණු වන සිසුවෙකු සර්ගම් ගීතයක් තාලයට ගැයීමෙන් ලබාගන්නා ප්‍රධාන කුසලතාව කුමක්ද?", "රාගයේ ස්වර රටාව සහ තාල මාත්‍රා ඒකාබද්ධ කිරීම", "රාගයේ වර්ජිත ස්වර හඳුනා නොගැනීම", "බෙර වාදනයෙන් වෙන්වී ගැයීම", "තම්බුරාව නොමැතිව ගැයීම", "සර්ගම් ගීත ස්වර හා තාල සමමුහුර්තතාව ප්‍රගුණ කරවයි."),
        q("භූපාලි රාගයේ බණ්ඩිස් අවසානයේදී 'තාන්' ඉදිරිපත් කරන විට භාවිත කළ හැකි ස්වර මොනවාද?", "ස, රි, ග, ප, ධ පමණක්", "ස, රි, ග, ම, ප, ධ, නි සියල්ල", "ස, රි̱, ග̱, ම, ප, ධ̱, නි̱", "ස, රි, ග, ම්, ප, ධ, නි", "තාන් ගායනයේදී වුවද රාගයේ නියමිත ස්වර 5 ඉක්මවා නොයා යුතුය."),
        q("බිලාවල් රාගය තාලයට ගායනා කරන විට මන්ද්‍ර සප්තකයේ බහුලව යෙදිය හැකි ස්වර මොනවාද?", "නි̣, ධ̣, ප̣", "ම්̣, ග̱̣, රි̱̣", "කෝමල ධ̣ පමණක්", "කෝමල නි̣ පමණක්", "බිලාවල්හි සියලු ස්වර ශුද්ධ බැවින් මන්ද්‍ර සප්තකයේද ශුද්ධ නි̣, ධ̣, ප̣ යෙදේ."),
        q("කාෆි රාගයේ මධ්‍ය 'ස' සිට 'ම' දක්වා ගොස් ආපසු එන කෙටි අලාපයකදී 'ග' ස්වරය කෙසේ ගැයේද?", "කෝමල ගාන්ධාරය (ග̱) ලෙස", "ශුද්ධ ගාන්ධාරය (ග) ලෙස", "වර්ජිතව අත්හැර", "තීව්‍ර මධ්‍යමය (ම්) ලෙස", "කාෆිහි පූර්වාංග චලනයේදී කෝමල ගාන්ධාරය ප්‍රධාන වේ."),
        q("ඛමාජ් රාගයේ අන්තරාවේදී 'සඃ' ස්වරය පසුකර ඉහළට යන විට 'සඃ රිඃ ගඃ' ගැයිය හැකිද?", "නැත, ආරෝහණයේදී රි වර්ජිත බැවින් සඃ ගඃ ලෙස යා යුතුය", "ඔව්, තාර සප්තකයේදී රි අනිවාර්ය වේ", "ඔව්, කෝමල රි ගැයිය යුතුය", "නැත, තාර සප්තකයේදී ග වර්ජිතය", "රාගයේ ආරෝහණ රීතිය මධ්‍ය හා තාර සප්තක දෙකටම පොදුවේ බලපායි."),
        q("දේශ් රාගය අයත් වන්නේ උත්තර භාරතීය ථාට දහයෙන් කුමන ථාටයටද?", "ඛමාජ් ථාටය", "කල්‍යාණ් ථාටය", "කාෆි ථාටය", "බිලාවල් ථාටය", "ශුද්ධ නි සහ කෝමල නි යෙදෙන දේශ් ඛමාජ් ථාටයට අයත් වේ."),
        q("දුර්ගා රාගයේ ජාතිය හා ආරෝහණ ස්වර ගණන කොපමණද?", "ඕඩව - ඕඩව (ස්වර 5 බැගින්)", "ෂාඩව - සම්පූර්ණ (6 - 7)", "සම්පූර්ණ - සම්පූර්ණ (7 - 7)", "ඕඩව - සම්පූර්ණ (5 - 7)", "දුර්ගා රාගයේ ආරෝහණ හා අවරෝහණ දෙකේම ග හා නි වර්ජිතව ස්වර 5ක් ඇත."),
        q("10 ශ්‍රේණියේ රාග 4න් මධ්‍යම රාත්‍රී කාලයේ ගැයෙන රාගය වන කාෆි රාගයේ ථාටය කුමක්ද?", "කාෆි ථාටය", "ඛමාජ් ථාටය", "බිලාවල් ථාටය", "කල්‍යාණ් ථාටය", "කාෆි රාගය කාෆි ථාටයේ ප්‍රධාන ආශ්‍රය රාගයයි."),
        q("භූපාලි රාගයේ 'ස රි ග ප ධ සඃ' යන ස්වර මාලාවට බොහෝ දුරට සමාන නමුත් තීව්‍ර මධ්‍යමය ඇතුළත් වෙනත් රාගයක් නම් කරන්න.", "යමන් හෝ ශුද්ධ කල්‍යාණ් රාගය", "භෛරවී රාගය", "අසාවරී රාගය", "කාෆි රාගය", "කල්‍යාණ් ථාටයේම උපදින යමන් රාගයේ තීව්‍ර මධ්‍යමය හා නිෂාදය යෙදේ."),
        q("බිලාවල් රාගයෙහි 'ධ' ස්වරය වාදී වීම නිසා පෙනී යන එහි වේලා කාණ්ඩය කුමක්ද?", "උත්තරාංග ප්‍රධාන රාගයක් වීම", "පූර්වාංග ප්‍රධාන රාගයක් වීම", "සන්ධිප්‍රකාශ රාගයක් වීම", "අනියත කාල රාගයක් වීම", "ධෛවතය උත්තරාංගයේ පිහිටන බැවින් බිලාවල් උත්තරාංග ප්‍රධාන උදෑසන රාගයකි."),
        q("ඛමාජ් රාගයෙහි 'ග' ස්වරය වාදී ස්වරය වීම නිසා එය කුමන කාණ්ඩයට වැටේද?", "පූර්වාංග ප්‍රධාන රාගයක්", "උත්තරාංග ප්‍රධාන රාගයක්", "සන්ධිප්‍රකාශ රාගයක්", "ප්‍රභාත රාගයක්", "ග ස්වරය පූර්වාංගයේ පිහිටන බැවින් ඛමාජ් රාත්‍රී කාලයේ පූර්වාංග ප්‍රධාන රාගයකි."),
        q("කාෆි රාගයට අයත් හෝලි ගීතයක් ගැයීමේදී වැඩි වශයෙන් භාවිත කරන තාලය කුමක්ද?", "ධමාර් හෝ ත්‍රිතාලය", "රූපක් තාලය පමණක්", "ඒක්තාලය පමණක්", "චෞතාලය පමණක්", "වසන්ත හෝලි ගීත සඳහා ධමාර් හා ත්‍රිතාලය බහුලව යොදා ගැනේ."),
        q("ශුද්ධ රි, ග, ම, ධ, නි යෙදී ආරෝහණයේ ස්වර 5 ක්ද අවරෝහණයේ ස්වර 5 ක්ද ගන්නා 10 ශ්‍රේණියේ රාගය කුමක්ද?", "භූපාලි රාගය", "ඛමාජ් රාගය", "කාෆි රාගය", "බිලාවල් රාගය", "ශුද්ධ ස්වර පහක් පමණක් ගන්නා ඕඩව රාගය භූපාලියි."),
        q("10 ශ්‍රේණියේ සිසුවෙකු හාමෝනියමයෙන් 'ස ග ම ප ධ නි සඃ' වැයූ විට ඔහු වයමින් සිටින රාගයේ ආරෝහණය කුමක්ද?", "ඛමාජ් රාගයේ ආරෝහණය", "භූපාලි රාගයේ ආරෝහණය", "කාෆි රාගයේ ආරෝහණය", "බිලාවල් රාගයේ ආරෝහණය", "රි වර්ජිතව ශුද්ධ ස-ග-ම-ප-ධ-නි-සඃ වැයෙන්නේ ඛමාජ් ආරෝහණයේදීය."),
        q("රාගයක් වයන විට හෝ ගයන විට එම රාගයේ 'වාදී ස්වරය' වැරදී වෙනත් ස්වරයක් අධිකව යෙදුවහොත් කුමක් සිදුවේද?", "රාගයේ මූලික ස්වරූපය වෙනස් වී වෙනත් රාගයකට හැරිය හැකිය", "සියලු ස්වර කෝමල බවට පත්වේ", "තාලයේ සම අතුරුදන් වේ", "ගායනය තාර සප්තකයට මාරු වේ", "වාදී ස්වරය වෙනස් වීමෙන් රාගයේ අනන්‍යතාව නැති වී යයි."),
        q("ඛමාජ් රාගයේ අවරෝහණයේදී යෙදෙන 'නි̱' ස්වරය සහ දේශ් රාගයේ අවරෝහණයේදී යෙදෙන 'නි̱' ස්වරය අතර සමානකම කුමක්ද?", "දෙකේම කෝමල නිෂාදය අවරෝහණ චලනයේ යෙදීම", "දෙකම තීව්‍ර නිෂාද වීම", "දෙකම ෂඩ්ජයට සමාන වීම", "දෙකම ආරෝහණයේ යෙදීම", "එකම ඛමාජ් ථාටයේ බැවින් ඛමාජ් හා දේශ් දෙකේම අවරෝහණයේ කෝමල නි යෙදේ."),
        q("භූපාලි රාගයේ 'ධ ප ග රි ස' යන අවරෝහණ ස්වර ඛණ්ඩය අවසන් කිරීමෙන් පසු රාගයේ විශ්‍රාමය ගන්නේ කුමන ස්වරය මතද?", "මධ්‍ය ෂඩ්ජය (ස)", "මන්ද්‍ර පංචමය (ප̣)", "තාර ෂඩ්ජය (සඃ)", "ශුද්ධ නිෂාදය (නි)", "සෑම රාගයකම අවසන් ස්ථිර විශ්‍රාමය මධ්‍ය ෂඩ්ජය මත සිදු වේ."),
        q("බිලාවල් රාගය සඳහා 'ධ' වාදී ස්වරය වන අතර 'සංවාදී' ස්වරය වන ගාන්ධාරය සමඟ එය පවත්වන ශ්‍රැති පරතරය කුමක්ද?", "ශ්‍රැති 9 ක් හෝ 13 ක ෂඩ්ජ-මධ්‍යම සබඳතාව", "ශ්‍රැති 2 ක සබඳතාව", "ශ්‍රැති 4 ක සබඳතාව", "ශ්‍රැති 22 ක සබඳතාව", "ග සහ ධ අතර ඇති සම්මත සංවාදී පරතරය අනුව එම යුගලය සැකසී ඇත."),
        q("කාෆි රාගයේ 'ස රි ග̱ ම ප' කොටසේ ගාන්ධාරය කෝමල වන නමුත් එහි රිෂභය කුමන ස්වරයක්ද?", "ශුද්ධ රිෂභය (රි)", "කෝමල රිෂභය (රි̱)", "තීව්‍ර රිෂභය", "වර්ජිත රිෂභය", "කාෆි රාගයේ රි සහ ධ සැමවිටම ශුද්ධ ස්වර ලෙස පවතී."),
        q("භූපාලි රාගයේදී 'ප ග රි ස' ලෙස බසින විට පංචමයෙන් පසු කෙළින්ම ගාන්ධාරයට එන්නේ කවර ස්වරය අත්හැරද?", "මධ්‍යමය (ම)", "රිෂභය (රි)", "ධෛවතය (ධ)", "නිෂාදය (නි)", "භූපාලි රාගයේ මධ්‍යමය සම්පූර්ණයෙන්ම වර්ජිත වන බැවින් ප-ග පැනීම සිදු වේ."),
        q("භූපාලි රාගයේ 'ස, රි, ග, ප, ධ' යන ස්වර පහ සප්තකයේ පූර්වාංගය හා උත්තරාංගය අතර කෙසේ බෙදී පවතීද?", "පූර්වාංගයේ ස-රි-ග ද උත්තරාංගයේ ප-ධ ද පිහිටයි", "පූර්වාංගයේ සියලුම ස්වර පහ පිහිටයි", "උත්තරාංගයේ සියලුම ස්වර පහ පිහිටයි", "මන්ද්‍ර සප්තකයේ පමණක් ස්වර පහ පිහිටයි", "පූර්වාංගයේ ම ද උත්තරාංගයේ නි ද වර්ජිත බැවින් මෙසේ බෙදේ."),
        q("භූපාලි රාගයේ චෝටා ඛයාල් හෝ ලක්ෂණ ගීතයක් ආරම්භ කිරීමේදී බහුලව යොදන මන්ද්‍ර ස්වරය කවරේද?", "මන්ද්‍ර ධෛවතය (ධ̣)", "මන්ද්‍ර මධ්‍යමය (ම̣)", "මන්ද්‍ර නිෂාදය (නි̣)", "මන්ද්‍ර කෝමල ගාන්ධාරය", "නි වර්ජිත නිසා භූපාලිහි මන්ද්‍ර කලාපයේ ධ̣ සහ ප̣ බහුලව යෙදේ."),
        q("බිලාවල් රාගය සහ කල්‍යාණ් රාගය සැසඳීමේදී ශුද්ධ මධ්‍යමය (ම) යෙදෙන්නේ කුමන රාගයේද?", "බිලාවල් රාගයේ", "යමන් කල්‍යාණ් පමණක්", "ශුද්ධ යමන් රාගයේ", "භූපාලි රාගයේ", "බිලාවල් රාගයේ සියලු ස්වර ශුද්ධ වන බැවින් මධ්‍යමයද ශුද්ධ වේ."),
        q("අල්හෛයා බිලාවල් රාගයේ අවරෝහණයේදී කෝමල නිෂාදය (නි̱) යොදාගන්නා සුන්දර ස්වර ඛණ්ඩය කුමක්ද?", "ධ නි̱ ධ ප", "නි̱ ස රි ග", "ම් ප නි̱ සඃ", "ග̱ රි̱ ස", "අල්හෛයා බිලාවල් රාගයේ පමණක් අවරෝහණයේදී ධ-නි̱-ධ-ප ලෙස කෝමල නි ස්පර්ශ වේ."),
        q("බිලාවල් රාගය පුහුණු වීමෙන් ශිෂ්‍යයාට ලැබෙන මූලික ප්‍රායෝගික ප්‍රතිලාභය කුමක්ද?", "ශුද්ධ සප්තකයේ සියලුම ස්වර ස්ථාන නිවැරදිව පිහිටුවීමේ හැකියාව", "කෝමල ස්වර සියල්ල එකවර ගැයීම", "තීව්‍ර මධ්‍යමය පුහුණු වීම", "වර්ජිත ස්වර හතරක් මතක තබා ගැනීම", "බිලාවල් ශුද්ධ ස්වර පදනම සකස් කරන ප්‍රථම පාසල් රාගයකි."),
        q("බිලාවල් රාගයේ 'ම ග ම රි ස' වක්‍ර චලනයේදී 'ග' ස්වරයට පසුව කෙළින්ම 'රි' නොගෙන නැවත 'ම' ගන්නේ ඇයි?", "බිලාවල් රාගයේ සාම්ප්‍රදායික වක්‍ර අලංකාරය රැකීමට", "රිෂභය ආරෝහණයේ වර්ජිත නිසා", "ගාන්ධාරය කෝමල නිසා", "මධ්‍යමය තීව්‍ර නිසා", "ම-ග-ම-රි-ස යන වක්‍ර චලනය බිලාවල් රාගයට විශේෂ ලාලිත්‍යයක් දේ."),
        q("කාෆි රාගයේ 'ස රි ග̱ ම ප ධ නි̱ සඃ' ස්වර පෙළ බටහිර සංගීතයේ කුමන මාදිලියට (Mode) සමාන වේද?", "ඩෝරියන් මාදිලියට (Dorian Mode)", "අයෝනියන් මාදිලියට (Ionian Mode)", "ලිඩියන් මාදිලියට (Lydian Mode)", "ෆ්‍රිජියන් මාදිලියට (Phrygian Mode)", "කෝමල ග සහ කෝමල නි ඇති කාෆි ථාටය බටහිර Dorian scale හා සමාන වේ."),
        q("කාෆි රාගයේ බණ්ඩිස් ගීතවල 'ප ග̱ රි ස' හෝ 'ම ප ධ ම ප ග̱ රි' ගයන විට ගාන්ධාරයේ කෝමල ස්වභාවය ඉස්මතු වන්නේ කෙසේද?", "රිෂභයට සමීපව ග̱ ස්වරය මෘදුව ස්පර්ශ කරමින්", "ග ස්වරය තීව්‍ර ලෙස ඉහළ නංවා", "රිෂභය කෝමල රි බවට හරවා", "පංචමය සම්පූර්ණයෙන් අත්හැර", "ම හා රි අතර ග̱ මෘදුව රඳවා ගැනීමෙන් කාෆි රාගයේ කාන්තිය වැඩි වේ."),
        q("කාෆි රාගය ගායනා කිරීමේදී මධ්‍යම රාත්‍රී සීමාව තෝරාගැනීමට හේතු වන රසභාව ලක්ෂණය කුමක්ද?", "එහි ඇති මධුර ශෘංගාර හා භාවපූර්ණ සන්සුන් රසය", "රෞද්‍ර හා යුදමය ඝෝෂාව", "ප්‍රභාත සූර්ය උදාව පිළිගැනීම", "බීභත්ස හා භයානක බව", "රාත්‍රී නිශ්ශබ්දතාවේදී කාෆි රාගයේ මධුර රසය මනාව රසවිඳිය හැකිය."),
        q("ඛමාජ් රාගයේ ඨුම්රි හෝ සරල ගී ගායනයේදී 'ග ම ප ධ නි̱ ධ ප' ඛණ්ඩයෙන් පසු කුමන ස්වර කරා බැස එයිද?", "ම ග රි ස", "ම් ප ධ සඃ", "ග̱ රි̱ ස", "නි සඃ රිඃ", "අවරෝහණයේ ශුද්ධ ම, ග, රි, ස හරහා මධ්‍ය ෂඩ්ජයට බැස එයි."),
        q("ඛමාජ් රාගයේ සංවාදී ස්වරය වන නිෂාදය සම්බන්ධයෙන් පිළිපැදිය යුතු නියමය කුමක්ද?", "ආරෝහණයේ ශුද්ධ නි ද, අවරෝහණයේ කෝමල නි̱ ද යෙදීම", "දෙපසම කෝමල නි̱ පමණක් ගැයීම", "දෙපසම ශුද්ධ නි පමණක් ගැයීම", "නිෂාදය සම්පූර්ණයෙන් අත්හැරීම", "උභය නිෂාද නියමය ඛමාජ් රාගයේ අනිවාර්ය නීතියකි."),
        q("ඛමාජ් රාගය 'ස රි ග ම ප' ලෙස ආරම්භ කළහොත් සිදු වන ශාස්ත්‍රීය වරද කුමක්ද?", "ආරෝහණයේ වර්ජිත වූ රිෂභය යෙදීමෙන් රාග නියමය බිඳීම", "ගාන්ධාරය වර්ජිත වීම", "කෝමල නිෂාදය ආරෝහණයට පැමිණීම", "තීව්‍ර මධ්‍යමය ඇතුළත් වීම", "ඛමාජ් ආරෝහණයේ ස සිට කෙළින්ම ග ට යා යුතු අතර රි අත්හැරිය යුතුය."),
        q("දේශ් රාගයේදී 'ප ධ ම ග රි ග ස' වැනි ඛණ්ඩයක් ගයන විට ගාන්ධාරයේ පිහිටීම කෙබඳුද?", "ශුද්ධ ගාන්ධාරය ලෙස අවරෝහණයේ වක්‍රව යෙදේ", "කෝමල ගාන්ධාරය ලෙස යෙදේ", "අවරෝහණයේදීත් සම්පූර්ණ වර්ජිත වේ", "තීව්‍ර මධ්‍යමය බවට හැරේ", "දේශ් ආරෝහණයේ ග වර්ජිත වුවද අවරෝහණයේ ශුද්ධ ග සුන්දරව යෙදේ."),
        q("දේශ් රාගයේ ආරෝහණය නිවැරදිව සටහන් කර ඇති පිළිතුර තෝරන්න.", "ස රි ම ප නි සඃ", "ස ග ම ප ධ නි සඃ", "ස රි ග ප ධ සඃ", "ස රි ග̱ ම ප ධ නි̱ සඃ", "දේශ් රාගයේ ආරෝහණයේ ග සහ ධ වර්ජිත වන අතර නි ශුද්ධ වේ."),
        q("දේශ් රාගයේ ජාතිය නිවැරදිව දැක්වෙන විකල්පය කුමක්ද?", "ඕඩව - සම්පූර්ණ", "ඕඩව - ඕඩව", "ෂාඩව - සම්පූර්ණ", "සම්පූර්ණ - සම්පූර්ණ", "ආරෝහණයේ 5ක් (ස රි ම ප නි) ද අවරෝහණයේ ස්වර 7ම ද යෙදේ."),
        q("දුර්ගා රාගයේ 'ස රි ම ප ධ සඃ' ගයන විට උත්තරාංගයේ වර්ජිත ස්වරය කුමක්ද?", "නිෂාදය (නි)", "ධෛවතය (ධ)", "පංචමය (ප)", "ෂඩ්ජය (සඃ)", "දුර්ගා රාගයේ ආරෝහණ හා අවරෝහණ දෙකේම ග සහ නි අත්හැරේ."),
        q("දුර්ගා රාගය ගායනය සඳහා නියමිත ප්‍රශස්ත ගායන සමය කවදාද?", "රාත්‍රී දෙවන ප්‍රහරය", "පාන්දර අරුණෝදය", "දහවල් මධ්‍යහ්නය", "උදෑසන පළමු ප්‍රහරය", "රාත්‍රී 9.00 සිට 12.00 දක්වා කාලයේ දුර්ගා රාගය ගැයේ."),
        q("දුර්ගා රාගයේදී 'ම ප ධ ම රි , ධ̣ ස' යන ඛණ්ඩයෙන් ඉස්මතු කෙරෙන්නේ කුමක්ද?", "වාදී ධ සහ සංවාදී රි ස්වරවල ප්‍රබලතාව", "කෝමල ගාන්ධාරයේ සුන්දරත්වය", "තීව්‍ර මධ්‍යමයේ චලනය", "නිෂාද දෙකේ වෙනස", "ම-ප-ධ-ම-රි ගමන දුර්ගා රාගයේ හඳුනාගැනීමේ පකඩයයි."),
        q("10 ශ්‍රේණියේ රාග 4 අතරින් 'පූර්වාංගයේ ස්වර හතර'ම (ස රි ග ම) කිසිදු අඩුවක් නැතිව ශුද්ධව යෙදෙන රාගය කුමක්ද?", "බිලාවල් රාගය", "භූපාලි රාගය", "ඛමාජ් රාගය", "කාෆි රාගය", "භූපාලිහි ම නැත, ඛමාජ්හි රි ආරෝහණයේ නැත, කාෆිහි ග කෝමල වේ."),
        q("භූපාලි රාගයේදී ත්‍රිතාලයේ 1 සිට 16 දක්වා මාත්‍රා තුළ සර්ගම් ගීතයක් ගයන විට තාලයේ පළමු මාත්‍රාව හඳුන්වන්නේ කෙසේද?", "සම (X)", "ඛාලි (0)", "දෙවන තාලිය (2)", "තෙවන තාලිය (3)", "ඕනෑම රාගයක බණ්ඩිස් හෝ සර්ගම් තාලයේ 1 වන මාත්‍රාව සම මත කේන්ද්‍ර වේ."),
        q("කාෆි රාගයේ 'ප ම ග̱ රි ස' ලෙස බසින විට පංචමයෙන් පහළ සියලු ස්වර අතුරින් විකෘති වන්නේ කුමක්ද?", "ගාන්ධාරය (ග̱) පමණි", "රිෂභය (රි̱) පමණි", "මධ්‍යමය (ම්) පමණි", "රි සහ ග යන දෙකම", "කාෆිහි ප, ම, රි, ස ශුද්ධ වන අතර ග පමණක් කෝමල වේ."),
        q("ඛමාජ් රාගය සහ දේශ් රාගය අතර ආරෝහණයේ පවතින ප්‍රධාන ස්වර වෙනස කුමක්ද?", "ඛමාජ්හි ග-ධ ඇති මුත් රි නැත; දේශ්හි රි ඇති මුත් ග-ධ නැත", "දෙකේම ආරෝහණ ස්වර සම්පූර්ණ වේ", "දේශ්හි තීව්‍ර ම් යෙදේ", "ඛමාජ්හි කෝමල රි යෙදේ", "ඛමාජ් ස-ග-ම-ප-ධ-නි-සඃ වන අතර දේශ් ස-රි-ම-ප-නි-සඃ වේ."),
        q("භූපාලි රාගයේ 'ස රි ග ප' සහ බිලාවල් රාගයේ 'ස රි ග ම ප' අතර වෙනසට හේතුව කුමක්ද?", "භූපාලිහි මධ්‍යමය වර්ජිත වීම", "බිලාවල්හි තීව්‍ර ම් යෙදීම", "භූපාලිහි ග කෝමල වීම", "බිලාවල්හි රි වර්ජිත වීම", "භූපාලි රාගයේ ම නැති නිසා ග සිට කෙළින්ම ප ට ගමන් කරයි."),
        q("රාගයක් ගැයීමට පෙර සිසුවා තම්බුරාව සමඟ සිය කටහඬ සුසර කරගත යුතු ප්‍රධාන ස්වර යුගලය කුමක්ද?", "ෂඩ්ජය (ස) සහ පංචමය (ප)", "මධ්‍යමය (ම) සහ තීව්‍ර මධ්‍යමය (ම්)", "කෝමල ගාන්ධාරය සහ කෝමල නිෂාදය", "කෝමල රිෂභය සහ ධෛවතය", "ස-ප යන අචල ස්වර දෙක 10 ශ්‍රේණියේ රාග හතරේම (භූපාලි, බිලාවල්, කාෆි, ඛමාජ්) අනිවාර්යයෙන් යෙදේ."),
        q("කාෆි රාගයේ සර්ගම් ගීතයකදී 'ස රි ග̱ ම , ග̱ රි ස' ලෙස ගැයෙන ඛණ්ඩයෙන් සිසුවාට පුහුණු වන්නේ කුමක්ද?", "ශුද්ධ රිෂභය සමඟ කෝමල ගාන්ධාරය නිවැරදිව ගැයීම", "තීව්‍ර මධ්‍යමය අන්දෝලනය කිරීම", "කෝමල ධෛවතය හඳුනා ගැනීම", "ආරෝහණයේ ස්වර හයක් අත්හැරීම", "ශුද්ධ රි සහ කෝමල ග අතර අර්ධ ස්වර පරතරය මනාව මෙයින් හුරු වේ."),
        q("ඛමාජ් රාගයේ අවරෝහණයේ 'සඃ නි̱ ධ ප ම ග' යන්න කාෆි රාගයේ එම කොටසින් වෙනස් වන්නේ කුමන ස්වරයෙන්ද?", "ගාන්ධාරයෙන් (ඛමාජ්හි ශුද්ධ ග ද කාෆිහි කෝමල ග̱ ද යෙදේ)", "නිෂාදයෙන් (ඛමාජ්හි ශුද්ධ නි ද කාෆිහි තීව්‍ර නි ද යෙදේ)", "ධෛවතයෙන් (දෙකේම ධ වර්ජිත වේ)", "මධ්‍යමයෙන් (ඛමාජ්හි තීව්‍ර ම් යෙදේ)", "උත්තරාංගයේ දෙකේම නි̱ ධ ප ම සමාන වුවත් ග ස්වරයේදී වෙනස හඳුනාගනී."),
        q("භූපාලි රාගය 10 ශ්‍රේණියේ බොහෝ සිසුන්ට ගැයීමට පහසු හා ජනප්‍රිය වීමට හේතුව කුමක්ද?", "සියලුම ස්වර ශුද්ධ වීම සහ විකෘති ස්වර නොතිබීම", "විකෘති ස්වර හතරක් යෙදීම", "සංකීර්ණ මිශ්‍ර තාල පමණක් භාවිත කිරීම", "මධ්‍යම රාත්‍රී දෙවන ප්‍රහරයේ පමණක් ගැයීම", "ස-රි-ග-ප-ධ යන ශුද්ධ පංචස්වර මාලාව ස්වාභාවිකව මිහිරිව ගලා යයි."),
        q("බිලාවල් රාගය සඳහා 'ධ ප ග ම රි ස' ලෙස වැරදීමකින් 'ම' ස්වරය අත්හැර 'ධ ප ග රි ස' ගැයුවහොත් එය කුමන රාගයට හැරේද?", "භූපාලි රාගයේ ස්වරූපයට", "කාෆි රාගයේ ස්වරූපයට", "භෛරවී රාගයේ ස්වරූපයට", "තෝඩි රාගයේ ස්වරූපයට", "ම සහ නි මඟහැර ස රි ග ප ධ පමණක් ගැයුවහොත් භූපාලි ඡායාව මතු වේ."),
        q("ඛමාජ් රාගයේ අන්තරා කොටසේදී 'ග ම ධ නි සඃ , සඃ නි̱ ධ ප' ලෙස ගැයීමේදී පෙනෙන සුවිශේෂීත්වය කුමක්ද?", "තාර සඃ වෙත යාමේදී ශුද්ධ නි ද ආපසු ඒමේදී කෝමල නි̱ ද යෙදීම", "දෙපසම තීව්‍ර ම් යෙදීම", "ධෛවතය කෝමල වීම", "ෂඩ්ජය මන්ද්‍ර වීම", "අන්තරාව තුළ උභය නිෂාදයේ වෙනස ඉතා පැහැදිලිව ඇසේ."),
        q("කාෆි රාගයේ ස්ථායි ගායනයේදී 'ප ධ ම ප ග̱ රි' යන ඛණ්ඩය වැදගත් වන්නේ ඇයි?", "කාෆි රාගයේ පූර්ණ අනන්‍යතාව සහ භාවය ප්‍රකට කරන බැවින්", "එය භූපාලි රාගයේ පකඩය බැවින්", "එහි තීව්‍ර මධ්‍යමය ඇති බැවින්", "එහි රිෂභය වර්ජිත බැවින්", "මධ්‍යමය හරහා කෝමල ග̱-රි වෙත බැසීම කාෆි රාගයේ මුඛ්‍ය ලක්ෂණයයි."),
        q("දුර්ගා රාගයේ බණ්ඩිස් ගීතයකදී 'ම ප ධ සඃ , ධ ප ම රි ස' යන ඛණ්ඩයේ අඩංගු ස්වර මොනවාද?", "ස, රි, ම, ප, ධ යන ස්වර පහ පමණි", "ස, රි, ග, ප, ධ යන ස්වර පහ පමණි", "ස, ග, ම, ධ, නි යන ස්වර පහ පමණි", "ස, රි, ග, ම, ප, ධ, නි ස්වර හතම", "දුර්ගා ඕඩව රාගයේ ග සහ නි සම්පූර්ණයෙන්ම වර්ජිත වේ."),
        q("දේශ් රාගයේදී 'ප ම ග රි , ග නි̣ ස' යන අවසන් ඛණ්ඩයෙන් පැහැදිලි වන මන්ද්‍ර ස්වරය කුමක්ද?", "මන්ද්‍ර ශුද්ධ නිෂාදය (නි̣)", "මන්ද්‍ර කෝමල ධෛවතය (ධ̱̣)", "මන්ද්‍ර තීව්‍ර මධ්‍යමය (ම්̣)", "මන්ද්‍ර කෝමල රිෂභය (රි̱̣)", "ආරෝහණ දිශාවට මන්ද්‍ර නි සිට ස ට යාමේදී ශුද්ධ නි̣ යෙදේ."),
        q("10 ශ්‍රේණියේ රාග 4න් 'රාත්‍රී කාලයේ' ගැයීමට නියමිත රාග තුන මොනවාද?", "භූපාලි, ඛමාජ් සහ කාෆි", "බිලාවල්, භෛරව් සහ අසාවරී", "භූපාලි, බිලාවල් සහ කාෆි", "බිලාවල්, ඛමාජ් සහ දුර්ගා", "බිලාවල් උදෑසන ගැයෙන අතර භූපාලි (රාත්‍රී 1), ඛමාජ් (රාත්‍රී 2) හා කාෆි (රාත්‍රී 3) රාත්‍රියේ ගැයේ."),
        q("10 ශ්‍රේණියේ රාග 4 අතරින් 'උදෑසන කාලයේ' ගැයීමට නියමිත එකම ප්‍රධාන රාගය කුමක්ද?", "බිලාවල් රාගය", "භූපාලි රාගය", "ඛමාජ් රාගය", "කාෆි රාගය", "දිවා ප්‍රථම ප්‍රහරයේ හෙවත් උදෑසන ගැයෙන්නේ බිලාවල් රාගයයි."),
        q("භූපාලි රාගයේ සංවාදී ස්වරය කවර ස්වරයද?", "ධෛවතය (ධ)", "ගාන්ධාරය (ග)", "රිෂභය (රි)", "පංචමය (ප)", "භූපාලිහි වාදී ස්වරය 'ග' වන අතර සංවාදී ස්වරය 'ධ' වේ."),
        q("බිලාවල් රාගයේදී 'ප ධ නි සඃ' ගැයීමේදී නිෂාදය කෝමල නොකර ශුද්ධව ගැයීමෙන් ලැබෙන භාවය කුමක්ද?", "උදෑසන ප්‍රබෝධමත් හා ධෛර්යසම්පන්න බව", "මධ්‍යම රාත්‍රී ශෝකජනක බව", "විරහ වේදනාව", "අතිශය භයානක බව", "ශුද්ධ ස්වර සමඟ බිලාවල් රාගය පිබිදෙන උදෑසන නැවුම් බව දනවයි."),
        q("ඛමාජ් රාගයේ සමහර ස්ථානවල 'ග ම ප ග ම රි ස' ලෙස ගැයෙන නමුත් ඛමාජ්හි බහුලව යෙදෙන 'ධ ම ප ග ම ග' කොටස කුමක්ද?", "වක්‍ර ස්වර සංචලන අලංකාරයකි", "තාල භංග වන දෝෂයකි", "භෛරව් රාගයේ ආරම්භයකි", "වර්ජිත ස්වර භාවිතයකි", "ධ සිට ම ප ග ම ග ලෙස කෙරෙන චලනය ඛමාජ් රාගයට චමත්කාරයක් දේ."),
        q("කාෆි රාගයේ බණ්ඩිස් ගීත ගායනයේදී බහුලව යෙදෙන 'ටප්පා' හෝ 'ඨුම්රි' අංග මගින් ප්‍රකට වන්නේ කුමක්ද?", "රාගයේ අර්ධ ශාස්ත්‍රීය ලාලිත්‍යය හා නම්‍යශීලී බව", "රාගයේ ස්වර 3ක් අඩු බව", "තබ්ලාව නැතිව ගැයීම", "බටහිර පියානෝ සංයෝජනය", "කාෆි ඨුම්රි, හෝලි සහ භජන් ගායනයට ඉතා සුදුසු නම්‍යශීලී රාගයකි."),
        q("10 ශ්‍රේණියේ රාග පිළිබඳ විභාග ප්‍රශ්නයකදී 'ඕඩව - ඕඩව' ජාතිය සඳහා දිය හැකි නිවැරදිම උදාහරණය කුමක්ද?", "භූපාලි රාගය (හෝ දුර්ගා රාගය)", "කාෆි රාගය", "ඛමාජ් රාගය", "බිලාවල් රාගය", "ස්වර 5 බැගින් ගන්නා භූපාලි හා දුර්ගා ඕඩව-ඕඩව ජාතියේ වේ."),
        q("10 ශ්‍රේණියේ රාග 4 අතරින් 'ෂාඩව - සම්පූර්ණ' ජාතියට උදාහරණයක් ලෙස දැක්විය හැකි රාගය කුමක්ද?", "ඛමාජ් රාගය", "භූපාලි රාගය", "බිලාවල් රාගය", "කාෆි රාගය", "ආරෝහණයේ 6 (රි වර්ජිත) හා අවරෝහණයේ 7 යෙදෙන්නේ ඛමාජ් රාගයේය."),
        q("10 ශ්‍රේණියේදී රාගයක 'පකඩ' (Pakad) යනුවෙන් උගන්වනු ලබන්නේ කුමක්ද?", "රාගය වහාම හඳුනාගත හැකි කෙටි මූලික ස්වර සමූහය", "ගීතයේ සම්පූර්ණ පදමාලාව", "තබ්ලාවේ ඨේකා බෝල් මාලාව", "වාද්‍ය භාණ්ඩය සුසර කරන යතුර", "කුඩා ස්වර සමූහයකින් රාගයේ සම්පූර්ණ ඡායාව හසුකර ගැනීම පකඩ නම් වේ."),
        q("භූපාලි රාගයේ මන්ද්‍ර සප්තකයේ 'ප̣ ධ̣ ස' ස්වර වැයීමේදී හාමෝනියම් හෝ වයලීනයෙන් ගැයිය යුත්තේ කුමන ස්වරද?", "ශුද්ධ ප̣ සහ ශුද්ධ ධ̣ සමඟ මධ්‍ය ස", "කෝමල ප̣ සහ කෝමල ධ̣", "තීව්‍ර ම්̣ සහ නි̣", "කෝමල ග̱̣ සහ රි̱̣", "භූපාලි රාගයේ මන්ද්‍ර සප්තකයේ ස්වරද ශුද්ධ ප̣ හා ශුද්ධ ධ̣ ලෙසම පවතී."),
        q("ඛමාජ් රාගයේ බණ්ඩිස් ගීතයක් 'තෙවන මාත්‍රාවෙන්' හෝ 'නවවන මාත්‍රාවෙන්' ආරම්භ වී 1 වන මාත්‍රාවට පැමිණි විට එම පළමු මාත්‍රාව කුමක්ද?", "සම (X)", "ඛාලි (0)", "අවසන් මාත්‍රාව", "වර්ජිත මාත්‍රාව", "බණ්ඩිස් ගීතයේ මුඛ්ඩාව කුමන මාත්‍රාවක ඇරඹුණත් 1 වන මාත්‍රාව වන සම මත කේන්ද්‍ර වේ."),
        q("කාෆි රාගයේ 'ස රි ග̱ ම ප' ගැයීමෙන් පසු 'ම ප ධ නි̱ සඃ' ගැයූ විට ආවරණය වන්නේ කුමන කොටස් දෙකද?", "පූර්වාංගය සහ උත්තරාංගය", "මන්ද්‍ර සප්තකය පමණක්", "වර්ජිත ස්වර යුගලය", "ඛාලි සහ තාලි කොටස්", "ස-ම පූර්වාංගයද ප-සඃ උත්තරාංගයද මෙයින් සම්පූර්ණ වේ."),
        q("බිලාවල් රාගය 10 ශ්‍රේණියේ සිසුවෙකුට තබ්ලා සමඟ ගැයීමට සුදුසු වන්නේ කවර තාලයක් යටතේද?", "ත්‍රිතාලය හෝ ඒක්තාලය", "චෞතාලය පමණක්", "ධමාර් තාලය පමණක්", "සූලතාලය පමණක්", "ත්‍රිතාලය 10 ශ්‍රේණියේ රාග බණ්ඩිස් ගායනය සඳහා ප්‍රධාන තාලය ලෙස භාවිත කෙරේ."),
        q("10 ශ්‍රේණියේ ඉගැන්වූ රාග හතරම (භූපාලි, බිලාවල්, කාෆි, ඛමාජ්) අයත් වන්නේ කුමන සංගීත සම්ප්‍රදායටද?", "උත්තර භාරතීය හින්දුස්ථානි සංගීත පද්ධතියට", "බටහිර ජෑස් සංගීත පද්ධතියට", "ජපන් සාම්ප්‍රදායික ගගකු සංගීතයට", "පැරණි ග්‍රීක නාට්‍ය සංගීතයට", "ශ්‍රී ලංකාවේ O/L පෙරදිග සංගීත විෂය නිර්දේශය හින්දුස්ථානි රාග පද්ධතිය පදනම් කරගනී.")
    )
}
